"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7614],{82208:e=>{e.exports=JSON.parse('{"functions":[{"name":"resolveOdds","desc":"Returns a box\'s own `odds` table, or [ShopPricing.DEFAULT_BOX_ODDS] when the\\nbox omits one.","params":[{"name":"boxId","desc":"key in `ShopPricing.BOXES`","lua_type":"string"}],"returns":[{"desc":"","lua_type":"{ [string]: number }?"}],"function_type":"static","source":{"line":78,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"buildBoxPools","desc":"Groups every non-hidden, rated cosmetic whose `boxes` list contains `boxId`\\nby rarity, each list sorted by itemId for deterministic iteration.","params":[{"name":"boxId","desc":"box to scan the catalog for","lua_type":"string"}],"returns":[{"desc":"rarity -> sorted itemIds","lua_type":"{ [string]: { string } }"}],"function_type":"static","private":true,"source":{"line":99,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"validateBoxes","desc":"Startup validation, called from [BoxService.init]: for every stocked box\\nin `ShopPricing.BOXES`, asserts its resolved odds sum to 1 (within\\n`SUM_EPSILON`) and every rarity with odds > 0 has at least one pool item.\\n`error()`s loudly on either violation. A box with no pool items at all is\\nunstocked: it warns and is skipped, and [BoxService.getBoxInfo] reports it\\nas absent so the shop never lists it.","params":[],"returns":[],"function_type":"static","source":{"line":137,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"getPityCount","desc":"Reads the player\'s current opens-since-Legendary+ counter for a box.\\nMissing keys mean 0 (never opened).","params":[{"name":"player","desc":"profile owner","lua_type":"Player"},{"name":"boxId","desc":"box to read","lua_type":"string"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","private":true,"source":{"line":187,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"setPityCount","desc":"Persists the player\'s opens-since-Legendary+ counter for a box and\\nreplicates it.","params":[{"name":"player","desc":"profile owner","lua_type":"Player"},{"name":"boxId","desc":"box to write","lua_type":"string"},{"name":"count","desc":"new counter value","lua_type":"number"}],"returns":[],"function_type":"static","private":true,"source":{"line":206,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"isPlayerRestricted","desc":"`PolicyService:GetPolicyInfoForPlayerAsync`\'s `ArePaidRandomItemsRestricted`\\nfor this player. A pcall failure or a missing policy result is treated as\\nrestricted, matching [BoxService.open]\'s gate.","params":[{"name":"player","desc":"player to check","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","private":true,"source":{"line":231,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"getBoxInfo","desc":"Everything the box window needs: price, resolved odds, the box\'s full pool\\n(sorted rarity then name), the pity guarantee, the buying player\'s current\\npity counter, and whether this player is policy-restricted from paid\\nrandom items (see [BoxService.isPlayerRestricted]) \u2014 the client hides the\\npurchase/open entry point when `restricted` is true.","params":[{"name":"boxId","desc":"box to describe","lua_type":"string"},{"name":"player","desc":"player whose pity counter/restriction to read","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"ShopTypes.BoxInfo?"}],"function_type":"static","source":{"line":274,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"rollTier","desc":"Cumulative roll over `RARITIES` in ascending order using `odds`.","params":[{"name":"rng","desc":"generator to roll with","lua_type":"Random"},{"name":"odds","desc":"resolved per-rarity odds","lua_type":"{ [string]: number }"}],"returns":[{"desc":"the rolled rarity","lua_type":"string"}],"function_type":"static","private":true,"source":{"line":333,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"rollForcedLegendaryTier","desc":"Re-rolls the tier proportionally across only the Legendary+ tiers with\\nodds > 0. Used when hard pity forces a guaranteed Legendary+ result.","params":[{"name":"rng","desc":"generator to roll with","lua_type":"Random"},{"name":"odds","desc":"resolved per-rarity odds","lua_type":"{ [string]: number }"}],"returns":[{"desc":"the rolled rarity, always Legendary or better","lua_type":"string"}],"function_type":"static","private":true,"source":{"line":359,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"rollTierWithPity","desc":"Rolls a tier, applying hard pity: when `pityCount` has reached\\n`pityOpens - 1` (this open is the Nth) and the natural roll came out below\\nLegendary, re-rolls at the tier level restricted to Legendary+.","params":[{"name":"rng","desc":"generator to roll with","lua_type":"Random"},{"name":"odds","desc":"resolved per-rarity odds","lua_type":"{ [string]: number }"},{"name":"pityCount","desc":"opens since the last Legendary+ pull","lua_type":"number"},{"name":"pityOpens","desc":"guarantee window","lua_type":"number"}],"returns":[{"desc":"the rolled rarity","lua_type":"string"}],"function_type":"static","private":true,"source":{"line":409,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"roll","desc":"Rolls a single item for `boxId` against the player\'s current pity state,\\nupdates and persists the pity counter, and returns the rolled itemId.\\nInside a protected tier ([DuplicateProtection]) the item is one the player\\ndoesn\'t own while any is left. Does not grant the item or touch currency \u2014\\nsee [BoxService.open].","params":[{"name":"player","desc":"roller, for reading/writing pity","lua_type":"Player"},{"name":"boxId","desc":"box to roll against","lua_type":"string"}],"returns":[{"desc":"rolled itemId, or nil when the box/pool cannot be resolved","lua_type":"string?"}],"function_type":"static","source":{"line":448,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"open","desc":"Purchase-and-open in one call \u2014 there are no box keys. Order:\\n\\n1. Flag + boxId validation.\\n2. `PolicyService:GetPolicyInfoForPlayerAsync` \u2014 rejects (closed, no debit)\\n   when the call fails or reports `ArePaidRandomItemsRestricted`.\\n3. Charges the box price in coins, mirroring\\n   [DailyRotationService.purchase]\'s debit + `Sink` analytics + refund flow.\\n4. Rolls (and persists pity) via [BoxService.roll].\\n5. Grants the result via [InventoryService.addQuantityToItemId]. Below\\n   [DuplicateProtection.MIN_RARITY] grants may repeat by design (trade-ups\\n   and quick-sell use them); protected tiers give a new item while one is\\n   left.\\n6. Refunds on any failure past the debit.","params":[{"name":"player","desc":"buyer","lua_type":"Player"},{"name":"boxId","desc":"box to open","lua_type":"string"}],"returns":[{"desc":"","lua_type":"ShopTypes.ShopBoxOpenResult?"}],"function_type":"static","source":{"line":503,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"tradeUp","desc":"Consumes `TradeUpContract.SLOT_COUNT` owned cosmetics of one rarity and\\ngrants one random cosmetic of the next rarity that has items\\n([TradeUpContract.nextRarity] skips empty tiers). The result pool is the\\nnext-rarity pool of a box drawn with weights from the inputs\' box\\nmemberships (an input in N boxes counts 1/N toward each; inputs in no box\\ncount toward the whole catalog). When every input shares a subtype and the\\npool holds that subtype, the pool narrows to it; a protected result tier\\n([DuplicateProtection]) then prefers items the player doesn\'t own. Same\\npolicy gate as\\n[BoxService.open]. The rarity rule and ceiling are [TradeUpContract]\'s,\\nthe same ones the window slots by. Starter items\\n([InventoryUtil.isStarterItem]) are refused. Inputs are only consumed\\nafter every check passes; an equipped item cannot be consumed down to\\nzero.","params":[{"name":"player","desc":"trader","lua_type":"Player"},{"name":"itemIds","desc":"one entry per slotted copy","lua_type":"{ string }"}],"returns":[{"desc":"`{ itemId }` on success, `{ error }` when refused","lua_type":"ShopTypes.ShopTradeUpResult"}],"function_type":"static","source":{"line":642,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"selfCheck","desc":"Studio-only sanity check: asserts [BoxService.validateBoxes] passes, then\\nsimulates `SELF_CHECK_SIMULATED_OPENS` opens of the in-memory pity state\\nmachine for every box (no player, no currency, no grants), asserting a\\nLegendary+ result occurs within every `pityOpens`-length window of opens \u2014\\nproving the hard-pity guarantee holds independent of the natural odds.\\nOnly called from [BoxService.init] under `RunService:IsStudio()`.","params":[],"returns":[],"function_type":"static","source":{"line":772,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"openPaid","desc":"[BoxService.open] minus the coin debit \u2014 the Robux receipt is the\\npayment, so there is nothing to charge or refund here. Runs the same\\nflag/box/policy validation, rolls (persisting pity), and grants.\\nReturning nil makes the receipt callback fail, so Roblox retries the\\ngrant later.","params":[{"name":"player","desc":"buyer","lua_type":"Player"},{"name":"boxId","desc":"box to open","lua_type":"string"}],"returns":[{"desc":"","lua_type":"ShopTypes.ShopBoxOpenResult?"}],"function_type":"static","source":{"line":817,"path":"src/Server/Features/Shop/BoxService.luau"}},{"name":"init","desc":"No-op unless `FeatureFlags.Crates` is on. Otherwise runs\\n[BoxService.validateBoxes] always, plus [BoxService.selfCheck] in Studio,\\nand registers the Robux box-open receipt callback (`type = \\"box\\"`,\\naction `box_<boxId>` \u2014 see rblxsync.yml\'s box dev products).","params":[],"returns":[],"function_type":"static","source":{"line":858,"path":"src/Server/Features/Shop/BoxService.luau"}}],"properties":[],"types":[],"name":"BoxService","desc":"Loot boxes with disclosed hard pity: purchase-and-open in a single call\\n(no keys \u2014 see docs/plans/monetization-catalog.md \\"No box keys\\" decision),\\ngated behind `PolicyService:GetPolicyInfoForPlayerAsync`\'s\\n`ArePaidRandomItemsRestricted` at the moment of purchase.\\n\\n## Odds model\\n\\nOdds live per box, at the rarity level ([ShopPricing.BoxDef.odds], or\\n[ShopPricing.DEFAULT_BOX_ODDS] when a box omits its own table). Per-item\\nchance is always derived \u2014 a rarity\'s odds split evenly across the pool\\nitems sharing that rarity \u2014 never stored. [BoxService.validateBoxes] enforces\\nat startup that every box\'s resolved odds sum to 1 and every rarity with\\nodds > 0 has at least one pool item.\\n\\n## Pity\\n\\nEach box carries a `pityOpens` guarantee: a Legendary+ result within that\\nmany opens. A per-player, per-box counter (`profile.box_pity[boxId]`) tracks\\nopens since the last Legendary+ pull. When the counter reaches\\n`pityOpens - 1` (this open is the Nth), a natural roll below Legendary is\\nre-rolled at the tier level, proportionally across the Legendary+ tiers\\nonly, then uniform within that tier. The counter resets to 0 on any\\nLegendary+ result, natural or forced.\\n\\nFeature-gated behind `FeatureFlags.Crates`.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":34,"path":"src/Server/Features/Shop/BoxService.luau"}}')}}]);